 * Splitting standard input into the three documents (mine, base, theirs).
 */

/**
 * Splits raw stdin text into lines, dropping the empty tail a trailing
 * newline leaves, then splits those lines into exactly three documents on
 * lines that are exactly `%%%`.
 *
 * @param {string} input - Raw standard input.
 * @returns {{ mine: string[], base: string[], theirs: string[] }}
 * @throws {Error} When the input does not hold exactly three parts.
 */
export function splitDocuments(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  const parts = [[]]
  for (const line of lines) {
    if (line === '%%%') {
      parts.push([])
    } else {
      parts[parts.length - 1].push(line)
    }
  }

  if (parts.length !== 3) {
    throw new Error('expected three parts separated by %%%')
  }

  const [mine, base, theirs] = parts
  return { mine, base, theirs }
}
"}

