{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e9-preset-craft-vs-plain-t5-20260919T125605Z/cell-BrQJZj/src/lcs.js","content":"/**
 * Longest common subsequence of whole lines between a base document and one
 * side, and the list of changes (replaced runs) the alignment implies.
 */

/**
 * Builds the LCS length table `length[i][j]`, the length of the longest
 * common subsequence of `base[i:]` and `side[j:]`.
 *
 * @param {string[]} base
 * @param {string[]} side
 * @returns {Int32Array[]} `length[i]` is a row of size `side.length + 1`.
 */
function buildLengthTable(base, side) {
  const m = base.length
  const n = side.length
  const table = new Array(m + 1)
  for (let i = 0; i <= m; i++) {
    table[i] = new Int32Array(n + 1)
  }
  for (let i = m - 1; i >= 0; i--) {
    for (let j = n - 1; j >= 0; j--) {
      if (base[i] === side[j]) {
        table[i][j] = table[i + 1][j + 1] + 1
      } else {
        const advanceBase = table[i + 1][j]
        const advanceSide = table[i][j + 1]
        table[i][j] = advanceBase >= advanceSide ? advanceBase : advanceSide
      }
    }
  }
  return table
}

/**
 * Walks the length table from the start of both documents, taking a match
 * whenever the current lines are equal and otherwise advancing whichever
 * side keeps the longer remaining subsequence, preferring to advance the
 * base on a tie.
 *
 * @param {string[]} base
 * @param {string[]} side
 * @param {Int32Array[]} table
 * @returns {Array<[number, number]>} Matched `[baseIndex, sideIndex]` pairs, in order.
 */
function walkMatches(base, side, table) {
  const matches = []
  let i = 0
  let j = 0
  const m = base.length
  const n = side.length
  while (i < m && j < n) {
    if (base[i] === side[j]) {
      matches.push([i, j])
      i++
      j++
    } else if (table[i + 1][j] >= table[i][j + 1]) {
      i++
    } else {
      j++
    }
  }
  return matches
}

/**
 * Computes the changes between `base` and `side`: runs of base lines
 * replaced by runs of side lines, wherever the LCS does not cover them.
 *
 * @param {string[]} base
 * @param {string[]} side
 * @returns {Array<{ start: number, end: number, sideStart: number, sideEnd: number }>}
 *   Changes ordered by base position; `start`/`end` index into `base`,
 *   `sideStart`/`sideEnd` index into `side`.
 */
export function diffChanges(base, side) {
  const table = buildLengthTable(base, side)
  const matches = walkMatches(base, side, table)

  const changes = []
  let prevBase = 0
  let prevSide = 0
  for (const [bi, sj] of matches) {
    if (bi > prevBase || sj > prevSide) {
      changes.push({ start: prevBase, end: bi, sideStart: prevSide, sideEnd: sj })
    }
    prevBase = bi + 1
    prevSide = sj + 1
  }
  if (prevBase < base.length || prevSide < side.length) {
    changes.push({ start: prevBase, end: base.length, sideStart: prevSide, sideEnd: side.length })
  }
  return changes
}
"}

