{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e9-preset-craft-vs-plain-t5-20260919T125605Z/cell-BrQJZj/src/regions.js","content":"/**
 * Grouping mine's and theirs's changes into merge regions, and resolving
 * each region's content against the base.
 */

/**
 * Merges mine's and theirs's changes, ordered by base position with mine
 * before theirs at a tie, into regions: maximal runs of overlapping or
 * touching changes.
 *
 * @param {Array<object>} mineChanges - From {@link diffChanges}, base vs mine.
 * @param {Array<object>} theirsChanges - From {@link diffChanges}, base vs theirs.
 * @returns {Array<{ start: number, end: number, changes: Array<object> }>}
 */
export function buildRegions(mineChanges, theirsChanges) {
  const combined = [
    ...mineChanges.map(change => ({ ...change, side: 'mine' })),
    ...theirsChanges.map(change => ({ ...change, side: 'theirs' })),
  ].sort((a, b) => a.start - b.start)

  const regions = []
  let current = null
  for (const change of combined) {
    if (current && change.start <= current.end) {
      current.end = Math.max(current.end, change.end)
      current.changes.push(change)
    } else {
      if (current) regions.push(current)
      current = { start: change.start, end: change.end, changes: [change] }
    }
  }
  if (current) regions.push(current)
  return regions
}

/**
 * Splits the full base range into an ordered sequence of stable stretches
 * (untouched by any change) and regions (touched by one or more changes).
 *
 * @param {number} baseLength
 * @param {Array<{ start: number, end: number, changes: Array<object> }>} regions
 * @returns {Array<{ type: 'stable' | 'region', start: number, end: number, changes?: Array<object> }>}
 */
export function buildSegments(baseLength, regions) {
  const segments = []
  let pos = 0
  for (const region of regions) {
    if (region.start > pos) {
      segments.push({ type: 'stable', start: pos, end: region.start })
    }
    segments.push({ type: 'region', start: region.start, end: region.end, changes: region.changes })
    pos = region.end
  }
  if (pos < baseLength) {
    segments.push({ type: 'stable', start: pos, end: baseLength })
  }
  return segments
}

/**
 * Maps a base index to the corresponding index into a side's own document,
 * using the offset from the side's last change ending at or before it. The
 * index must not fall strictly inside one of the side's own changes.
 *
 * @param {Array<object>} changes - A side's changes, ordered by base position.
 * @param {number} baseIndex
 * @returns {number}
 */
function mapBaseToSide(changes, baseIndex) {
  let offset = 0
  for (const change of changes) {
    if (change.end <= baseIndex) {
      offset = change.sideEnd - change.end
    } else {
      break
    }
  }
  return baseIndex + offset
}

function arraysEqual(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) {
    if (a[i] !== b[i]) return false
  }
  return true
}

/**
 * Resolves a region's content: mine's lines, the base's lines and theirs's
 * lines for the region, plus the resolution kind per the merge rules.
 *
 * @param {string[]} base
 * @param {string[]} mine
 * @param {string[]} theirs
 * @param {Array<object>} mineChanges - All of mine's changes, ordered.
 * @param {Array<object>} theirsChanges - All of theirs's changes, ordered.
 * @param {{ start: number, end: number, changes: Array<object> }} region
 * @returns {{ kind: 'mine' | 'theirs' | 'both' | 'conflict', mine: string[], base: string[], theirs: string[] }}
 */
export function resolveRegion(base, mine, theirs, mineChanges, theirsChanges, region) {
  const mineLines = mine.slice(mapBaseToSide(mineChanges, region.start), mapBaseToSide(mineChanges, region.end))
  const theirsLines = theirs.slice(mapBaseToSide(theirsChanges, region.start), mapBaseToSide(theirsChanges, region.end))
  const baseLines = base.slice(region.start, region.end)

  if (region.changes.length === 1) {
    return { kind: region.changes[0].side, mine: mineLines, base: baseLines, theirs: theirsLines }
  }
  if (arraysEqual(mineLines, theirsLines)) return { kind: 'both', mine: mineLines, base: baseLines, theirs: theirsLines }
  if (arraysEqual(mineLines, baseLines)) return { kind: 'theirs', mine: mineLines, base: baseLines, theirs: theirsLines }
  if (arraysEqual(theirsLines, baseLines)) return { kind: 'mine', mine: mineLines, base: baseLines, theirs: theirsLines }
  return { kind: 'conflict', mine: mineLines, base: baseLines, theirs: theirsLines }
}
"}

