import { diffChanges } from './lcs.js'
import { buildRegions, buildSegments, resolveRegion } from './regions.js'

/**
 * @typedef {{ type: 'stable' | 'mine' | 'theirs' | 'both', lines: string[] }
 *   | { type: 'conflict', mine: string[], base: string[], theirs: string[] }} MergeSegment
 */

/**
 * Computes the ordered list of merge segments for three documents.
 *
 * @param {string[]} mine
 * @param {string[]} base
 * @param {string[]} theirs
 * @returns {MergeSegment[]}
 */
export function mergeDocuments(mine, base, theirs) {
  const mineChanges = diffChanges(base, mine)
  const theirsChanges = diffChanges(base, theirs)
  const regions = buildRegions(mineChanges, theirsChanges)
  const segments = buildSegments(base.length, regions)

  return segments.map(segment => {
    if (segment.type === 'stable') {
      return { type: 'stable', lines: base.slice(segment.start, segment.end) }
    }
    const resolved = resolveRegion(base, mine, theirs, mineChanges, theirsChanges, segment)
    if (resolved.kind === 'conflict') {
      return { type: 'conflict', mine: resolved.mine, base: resolved.base, theirs: resolved.theirs }
    }
    const lines = resolved.kind === 'theirs' ? resolved.theirs : resolved.mine
    return { type: resolved.kind, lines }
  })
}
