/**
 * Renders segments as merged text, with full conflict markers.
 *
 * @param {import('./merge.js').MergeSegment[]} segments
 * @returns {{ lines: string[], hadConflict: boolean }}
 */
export function renderMerge(segments) {
  return render(segments, true)
}

/**
 * Renders segments as merged text, with conflict markers that omit the base.
 *
 * @param {import('./merge.js').MergeSegment[]} segments
 * @returns {{ lines: string[], hadConflict: boolean }}
 */
export function renderMerge2(segments) {
  return render(segments, false)
}

function render(segments, includeBase) {
  const lines = []
  let hadConflict = false
  for (const segment of segments) {
    if (segment.type === 'conflict') {
      hadConflict = true
      lines.push('<<<<<<< mine', ...segment.mine)
      if (includeBase) {
        lines.push('||||||| base', ...segment.base)
      }
      lines.push('=======', ...segment.theirs, '>>>>>>> theirs')
    } else {
      lines.push(...segment.lines)
    }
  }
  return { lines, hadConflict }
}

