  let hadConflict = false
  for (const segment of segments) {
    if (segment.type === 'conflict') {
      hadConflict = true
      lines.push(`conflict mine=${segment.mine.length} base=${segment.base.length} theirs=${segment.theirs.length}`)
    } else {
      lines.push(`${segment.type} ${segment.lines.length}`)
    }
  }
  return { lines, hadConflict }
}
